  "account.telegram.subtitle": { ru: "Подключите свой аккаунт Fleet GPS к приватному чату Telegram.", uk: "Підключіть свій обліковий запис Fleet GPS до приватного чату Telegram.", en: "Connect your Fleet GPS account to a private Telegram chat." },
