  "account.telegram.disconnectPrefsNote": { ru: "Настройки уведомлений сохранятся, но доставка прекратится, пока вы не подключите Telegram снова.", uk: "Налаштування сповіщень збережуться, але доставка припиниться, доки ви не підключите Telegram знову.", en: "Notification preferences stay saved, but delivery stops until you connect Telegram again." },
  "account.notifications.subtitle": { ru: "Выберите события и автомобили, о которых Fleet GPS будет уведомлять вас в Telegram.", uk: "Оберіть події та автомобілі, про які Fleet GPS повідомлятиме вас у Telegram.", en: "Choose the events and vehicles Fleet GPS should notify you about in Telegram." },
