  "admin.settings.speedGuidance": { ru: "Эти настройки, включая границу города, влияют на будущую оценку превышений и сбрасывают контекст подтверждения.", uk: "Ці налаштування, включно з межами міста, впливають на майбутню оцінку перевищень і скидають контекст підтвердження.", en: "These settings, including the city boundary, affect future speeding evaluation and reset confirmation context." },
  "admin.settings.inactivity": { ru: "Неактивность", uk: "Неактивність", en: "Inactivity" },
  "admin.settings.inactivityEnabled": { ru: "Правило включено", uk: "Правило увімкнено", en: "Rule enabled" },
  "admin.settings.inactivityDistance": { ru: "Порог расстояния", uk: "Поріг відстані", en: "Distance threshold" },
  "admin.settings.inactivityDuration": { ru: "Порог длительности", uk: "Поріг тривалості", en: "Duration threshold" },
  "admin.settings.inactivityGuidance": { ru: "Эти настройки влияют на будущую оценку неактивности и сбрасывают текущее окно неактивности.", uk: "Ці налаштування впливають на майбутню оцінку неактивності та скидають поточне вікно неактивності.", en: "These settings affect future inactivity evaluation and reset the current inactivity window." },
  "admin.settings.tripsStops": { ru: "Поездки и остановки", uk: "Поїздки та зупинки", en: "Trips & Stops" },
  "admin.settings.tripMovementSpeed": { ru: "Порог скорости движения", uk: "Поріг швидкості руху", en: "Movement speed threshold" },
  "admin.settings.tripMovementConfirmation": { ru: "Подтверждение движения", uk: "Підтвердження руху", en: "Movement confirmation" },
  "admin.settings.tripStopConfirmation": { ru: "Подтверждение остановки", uk: "Підтвердження зупинки", en: "Stop confirmation" },
  "admin.settings.tripDataGap": { ru: "Порог разрыва данных", uk: "Поріг розриву даних", en: "Data-gap threshold" },
  "admin.settings.tripsStopsGuidance": { ru: "Скорость определяет движение; подтверждения задают непрерывный сигнал до начала поездки или остановки; разрыв данных прерывает непрерывность. Изменения влияют и на исторические аналитические результаты: GPS-наблюдения не переписываются, но поездки, остановки и отчёты пересчитываются по текущей политике.", uk: "Швидкість визначає рух; підтвердження задають безперервний сигнал до початку поїздки або зупинки; розрив даних перериває безперервність. Зміни впливають і на історичні аналітичні результати: GPS-спостереження не переписуються, але поїздки, зупинки й звіти перераховуються за поточною політикою.", en: "Speed determines movement; confirmations require a continuous signal before a trip or stop begins; a data gap breaks continuity. Changes also affect historical analytical results: GPS observations are not rewritten, but trips, stops, and reports are recomputed using the current policy." },
  "admin.settings.geofence": { ru: "Городская геозона", uk: "Міська геозона", en: "City geofence" },
  "admin.settings.geofenceConfigured": { ru: "Настроено: колец {rings}, точек {points}.", uk: "Налаштовано: кілець {rings}, точок {points}.", en: "Configured: {rings} rings, {points} points." },
  "admin.settings.geofenceNotConfigured": { ru: "Не настроено.", uk: "Не налаштовано.", en: "Not configured." },
  "admin.settings.geofenceReadonly": { ru: "Для безопасного редактирования этого полигона в интерфейсе администрирования нужен отдельный редактор карты. Типизированный API принимает только проверенный GeoJSON Polygon.", uk: "Для безпечного редагування цього полігону в інтерфейсі адміністрування потрібен окремий редактор мапи. Типізований API приймає лише перевірений GeoJSON Polygon.", en: "A dedicated map editor is required before this polygon can be safely edited in the Administration UI. The typed API accepts only a validated GeoJSON Polygon." },
  "admin.settings.invalidField": { ru: "Некорректно: {field}. Проверьте указанные ограничения.", uk: "Некоректно: {field}. Перевірте вказані обмеження.", en: "Invalid {field}. Check the displayed limits." },
  "admin.settings.saveError": { ru: "Не удалось сохранить настройки. Проверьте значения и повторите попытку.", uk: "Не вдалося зберегти налаштування. Перевірте значення та повторіть спробу.", en: "Settings could not be saved. Check the values and retry." },
  "admin.settings.invalidResponse": { ru: "Не удалось сохранить настройки. Обновите страницу и повторите попытку.", uk: "Не вдалося зберегти налаштування. Оновіть сторінку та повторіть спробу.", en: "Settings could not be saved. Please reload and retry." },
  "admin.settings.conflict": { ru: "Настройки были изменены в другом сеансе. Обновите страницу перед повторной попыткой; ваши правки пока сохранены здесь.", uk: "Налаштування було змінено в іншому сеансі. Оновіть сторінку перед повторною спробою; ваші правки поки збережено тут.", en: "Settings were changed in another session. Reload before retrying; your edits are still kept here." },
  "admin.settings.reload": { ru: "Загрузить текущие настройки", uk: "Завантажити поточні налаштування", en: "Reload current settings" },
