  "admin.settings.refreshedPreserved": { ru: "Настройки обновлены до ревизии {revision}. Ваши несохранённые изменения сохранены.", uk: "Налаштування оновлено до ревізії {revision}. Ваші незбережені зміни збережено.", en: "Settings were refreshed to revision {revision}. Your unsaved changes were preserved." },
