  "history.population.confirmDurableTitle": { ru: "Подтвердите создание запуска", uk: "Підтвердьте створення запуску", en: "Confirm run creation" },
  "history.population.shortConfirmation": { ru: "Операция выполняется в этом запросе, обращается к GPS-провайдеру и может поэтапно сохранять работу. Оставьте страницу открытой.", uk: "Операція виконується в цьому запиті, звертається до GPS-провайдера й може поетапно зберігати роботу. Залиште сторінку відкритою.", en: "This operation runs in this request, contacts the GPS provider, and may commit work incrementally. Keep this page open." },
  "history.population.durableConfirmation": { ru: "Будет создана долговременная серверная работа. Она продолжится независимо после закрытия страницы и может обращаться к GPS-провайдеру.", uk: "Буде створено довготривалу серверну роботу. Вона триватиме незалежно після закриття сторінки й може звертатися до GPS-провайдера.", en: "Durable server-side work will be created. It continues independently after this page closes and may contact the GPS provider." },
  "history.population.shortConflictTitle": { ru: "Заполнение уже выполняется", uk: "Заповнення вже виконується", en: "Population is already running" },
  "history.population.shortConflictText": { ru: "Другая операция заполнения сейчас владеет общим ресурсом. Запрос не повторялся автоматически.", uk: "Інша операція заповнення зараз володіє спільним ресурсом. Запит не повторювався автоматично.", en: "Another population operation currently owns the shared resource. The request was not retried automatically." },
  "history.population.shortFailedTitle": { ru: "Короткое заполнение не завершено", uk: "Коротке заповнення не завершено", en: "Short population did not complete" },
  "history.population.shortFailedText": { ru: "Часть окон могла быть сохранена до ошибки. Отката и автоматической повторной отправки не выполнялось.", uk: "Частину вікон могло бути збережено до помилки. Відкату й автоматичного повторного надсилання не виконувалося.", en: "Some windows may have been committed before the failure. No rollback or automatic retry was performed." },
  "history.population.durableConflictTitle": { ru: "Долговременный запуск уже активен", uk: "Довготривалий запуск уже активний", en: "A durable run is already active" },
  "history.population.durableConflictText": { ru: "Проверено актуальное состояние активного запуска. Запрос на создание не повторялся автоматически.", uk: "Перевірено актуальний стан активного запуску. Запит на створення не повторювався автоматично.", en: "The authoritative active-run state was checked. The creation request was not retried automatically." },
  "history.population.durableFailedTitle": { ru: "Создание запуска не подтверждено", uk: "Створення запуску не підтверджено", en: "Run creation was not confirmed" },
  "history.population.durableFailedText": { ru: "Проверено актуальное состояние активного запуска. Автоматическая повторная отправка не выполнялась.", uk: "Перевірено актуальний стан активного запуску. Автоматичне повторне надсилання не виконувалося.", en: "The authoritative active-run state was checked. No automatic retry was made." },
  "history.population.durableCreatedTitle": { ru: "Долговременный запуск создан", uk: "Довготривалий запуск створено", en: "Durable run created" },
  "history.population.durableCreatedText": { ru: "Запуск принят сервером и может ожидать начала выполнения.", uk: "Запуск прийнято сервером і він може очікувати початку виконання.", en: "The server accepted the run; it may still be waiting to start." },
  "history.population.lastShortResult": { ru: "Последний результат короткого заполнения", uk: "Останній результат короткого заповнення", en: "Last short-population result" },
  "history.population.visitOnly": { ru: "Результат относится только к взаимодействию в этой вкладке и не является долговременной историей запусков.", uk: "Результат стосується лише взаємодії в цій вкладці й не є довготривалою історією запусків.", en: "This result belongs only to the interaction in this tab; it is not durable run history." },
