  "reports.description": { ru: "Ежедневная активность автопарка по сохранённым GPS-наблюдениям.", uk: "Щоденна активність автопарку за збереженими GPS-спостереженнями.", en: "Daily fleet activity from stored GPS observations." },
  "reports.reportName": { ru: "Активность автопарка за день", uk: "Активність автопарку за день", en: "Daily fleet activity" },
  "reports.refresh": { ru: "Обновить", uk: "Оновити", en: "Refresh" },
